mapper.select:
SELECT qnum, qtitle, qwriter, member_num, qcontent, qdate, row_num FROM ( SELECT q.qnum, q.qtitle, q.qwriter, q.member_num, q.qcontent, q.qdate,ROW_NUMBER() OVER(ORDER BY q.qnum DESC) AS row_num FROM qna_q q INNER JOIN member m ON q.member_num = m.num
AND q.qwriter LIKE '%' || #{searchValue} || '%' AND q.qtitle LIKE '%' || #{searchValue} || '%' AND q.qcontent LIKE '%' || #{searchValue} || '%'
) numbered_rows WHERE row_num BETWEEN #{begin} AND #{end}
